func Identity[T any](x T) T { return x }
type Transformer[T any] func(T) T
// Compose folds a chain with Identity as the base case; an empty chain reduces to the identity.
// Middleware pass-through: func Passthrough(next http.Handler) http.Handler { return next }
func Compose[T any](ts []Transformer[T]) Transformer[T] {
	return func(x T) T {
		for i := len(ts) - 1; i >= 0; i-- {
			x = ts[i](x)
		}
		return x
	}
}
